package com.mia.watchprobe;
import android.app.*;import android.os.*;import android.bluetooth.*;import android.bluetooth.le.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.view.*;import android.widget.*;import java.util.*;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity {
 BluetoothAdapter adapter; BluetoothLeScanner scanner; BluetoothGatt gatt; LinearLayout list; TextView status; Handler h=new Handler(); HashSet<String> seen=new HashSet<>(); boolean scanning=false; Runnable scanStopTask; int blue=Color.rgb(25,145,255);
 void log(String s){runOnUiThread(()->{TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(13);t.setPadding(8,8,8,8);list.addView(t);});}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(18,24,18,12);root.setBackgroundColor(Color.rgb(12,16,25));setContentView(root);
  TextView title=new TextView(this);title.setText("MIA WATCHPROBE");title.setTextSize(24);title.setTextColor(blue);root.addView(title);
  status=new TextView(this);status.setText("Analizador Bluetooth LE · Android");status.setTextColor(Color.LTGRAY);root.addView(status);
  Button scan=new Button(this);scan.setText("BUSCAR DISPOSITIVOS");root.addView(scan);
  ScrollView sv=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);sv.addView(list);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));
  BluetoothManager bm=(BluetoothManager)getSystemService(BLUETOOTH_SERVICE);adapter=bm.getAdapter();if(adapter!=null)scanner=adapter.getBluetoothLeScanner();
  scan.setOnClickListener(v->startScan());requestPerms();
 }
 void requestPerms(){if(Build.VERSION.SDK_INT>=31){ArrayList<String> p=new ArrayList<>();for(String s:new String[]{android.Manifest.permission.BLUETOOTH_SCAN,android.Manifest.permission.BLUETOOTH_CONNECT})if(checkSelfPermission(s)!=PackageManager.PERMISSION_GRANTED)p.add(s);if(!p.isEmpty())requestPermissions(p.toArray(new String[0]),9);}else if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION},9);}
 boolean allowed(){return Build.VERSION.SDK_INT<31||checkSelfPermission(android.Manifest.permission.BLUETOOTH_SCAN)==PackageManager.PERMISSION_GRANTED&&checkSelfPermission(android.Manifest.permission.BLUETOOTH_CONNECT)==PackageManager.PERMISSION_GRANTED;}
 void startScan(){if(!allowed()){requestPerms();return;}if(adapter==null||!adapter.isEnabled()){status.setText("Activa Bluetooth");return;}scanner=adapter.getBluetoothLeScanner();if(scanner==null){status.setText("Bluetooth LE no disponible. Apaga y enciende Bluetooth.");return;}try{if(scanStopTask!=null)h.removeCallbacks(scanStopTask);if(scanning)scanner.stopScan(callback);scanning=false;}catch(Exception ignored){}seen.clear();list.removeAllViews();status.setText("Buscando durante 15 segundos…");try{scanner.startScan(callback);scanning=true;scanStopTask=()->{try{if(scanning)scanner.stopScan(callback);}catch(Exception ignored){}scanning=false;status.setText("Búsqueda terminada · "+seen.size()+" dispositivos");};h.postDelayed(scanStopTask,15000);}catch(Exception e){scanning=false;status.setText("No se pudo iniciar el escaneo. Reinicia Bluetooth y prueba otra vez.");log(e.toString());}}
 ScanCallback callback=new ScanCallback(){public void onScanResult(int type,ScanResult r){BluetoothDevice d=r.getDevice();String id=d.getAddress();if(seen.add(id)){String name=d.getName();if(name==null||name.isEmpty())name=r.getScanRecord()!=null?r.getScanRecord().getDeviceName():"Sin nombre";final String n=name;runOnUiThread(()->{Button x=new Button(MainActivity.this);x.setText(n+"\n"+id+" · RSSI "+r.getRssi()+" dBm");list.addView(x);x.setOnClickListener(v->connect(d));});}}public void onScanFailed(int e){scanning=false;String msg=e==1?"El escaneo ya estaba iniciado; se ha detenido para permitir otro intento.":e==2?"Demasiadas aplicaciones están escaneando Bluetooth.":e==3?"La app no está registrada para escanear.":e==4?"Escaneo no disponible en este momento.":"Error desconocido";status.setText("Error Bluetooth "+e);log("Error de escaneo "+e+": "+msg);}};
 void connect(BluetoothDevice d){if(!allowed())return;status.setText("Conectando con "+d.getAddress());if(gatt!=null)gatt.close();gatt=d.connectGatt(this,false,gattCallback);}
 BluetoothGattCallback gattCallback=new BluetoothGattCallback(){
  public void onConnectionStateChange(BluetoothGatt g,int s,int state){if(state==BluetoothProfile.STATE_CONNECTED){log("CONECTADO · "+g.getDevice().getAddress());g.discoverServices();}else if(state==BluetoothProfile.STATE_DISCONNECTED)log("Desconectado · estado "+s);}
  public void onServicesDiscovered(BluetoothGatt g,int s){if(s!=BluetoothGatt.GATT_SUCCESS){log("Error descubriendo servicios: "+s);return;}for(BluetoothGattService service:g.getServices()){log("\nSERVICIO: "+service.getUuid()+" ["+service.getType()+"]");for(BluetoothGattCharacteristic c:service.getCharacteristics()){int p=c.getProperties();log("  CARACTERÍSTICA "+c.getUuid()+" · "+props(p));if((p&BluetoothGattCharacteristic.PROPERTY_READ)!=0)h.postDelayed(()->{try{g.readCharacteristic(c);}catch(Exception e){log("No se pudo solicitar lectura");}},500);if((p&BluetoothGattCharacteristic.PROPERTY_NOTIFY)!=0||(p&BluetoothGattCharacteristic.PROPERTY_INDICATE)!=0){g.setCharacteristicNotification(c,true);BluetoothGattDescriptor desc=c.getDescriptor(UUID.fromString("00002902-0000-1000-8000-00805f9b34fb"));if(desc!=null){desc.setValue((p&BluetoothGattCharacteristic.PROPERTY_NOTIFY)!=0?BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE:BluetoothGattDescriptor.ENABLE_INDICATION_VALUE);h.postDelayed(()->g.writeDescriptor(desc),900);}}}}}
  public void onCharacteristicRead(BluetoothGatt g,BluetoothGattCharacteristic c,int s){if(s==0)showValue(c,"LECTURA");else log("Lectura fallida "+c.getUuid()+" · "+s);}
  public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic c){showValue(c,"NOTIFICACIÓN");}
  void showValue(BluetoothGattCharacteristic c,String label){byte[] b=c.getValue();if(b==null)return;StringBuilder hex=new StringBuilder();for(byte x:b)hex.append(String.format("%02X ",x));log(label+" "+c.getUuid()+"\n HEX: "+hex+"\n TEXTO: "+new String(b,StandardCharsets.UTF_8));}
 };
 String props(int p){ArrayList<String>a=new ArrayList<>();if((p&2)!=0)a.add("READ");if((p&8)!=0)a.add("WRITE");if((p&4)!=0)a.add("WRITE_NO_RESPONSE");if((p&16)!=0)a.add("NOTIFY");if((p&32)!=0)a.add("INDICATE");return a.toString();}
 protected void onDestroy(){super.onDestroy();try{if(scanner!=null)scanner.stopScan(callback);if(gatt!=null)gatt.close();}catch(Exception e){}}
}
